// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 8: Read proposed items": "in1_Step8Readproposeditems"};
const LISTS = [];
const EXECUTED = ["Step 8: Each morning"];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 8: Read proposed items";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"id_q": encodeURIComponent(out.id), "expired_body": JSON.stringify({ status: 'expired' }), "log_body": JSON.stringify({ recipe: 'R14.1', item: out.id, decision: 'expired unverified', rules: { occurrence: out.occurrence_id, series: out.series_id } }), "failed_body": JSON.stringify({ recipe: 'R14.1', item: out.id, reason: 'write failed', detail: 'Expiry write failed; never retried', owner: $('Config').first().json.exception_owner })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Working days come from Config: the weekdays you work and your holiday dates.
const isWorkday = (d, cfg) => cfg.working_weekdays.includes(d.getUTCDay()) && !cfg.holidays.includes(d.toISOString().slice(0, 10));
const nextWorkday = (d, cfg) => { let x = new Date(d.getTime() + 86400000); while (!isWorkday(x, cfg)) x = new Date(x.getTime() + 86400000); return x; };
const todayUtc = () => new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');

// Step 8: a draft still unverified after its deadline (the end of the next working day) expires.
const today = todayUtc().toISOString().slice(0, 10);
const rows = ($('Step 8: Read proposed items').first().json.items || []).filter(r => r.status === 'proposed' && r.verify_by && r.verify_by < today);
return rows.map(r => ({ json: { id: r.id, occurrence_id: r.occurrence_id, series_id: r.series_id } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };

