const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 8: Expired drafts";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"owner_message": JSON.stringify({ to: [$('Config').first().json.register_owner], subject: out.count + ' draft action list(s) expired unverified', text: 'The chair or backup types these actions in: ' + out.lists.join('; ') }), "failed_body": JSON.stringify({ recipe: 'R14.1', item: 'expiry ' + new Date().toISOString().slice(0, 10), reason: 'write failed', detail: 'Message to the register owner failed; never retried: ' + out.lists.join('; '), owner: $('Config').first().json.exception_owner })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// One message to the register owner listing the expired drafts.
const rows = $input.all().map((_, i) => $('Step 8: Rule: past the deadline?').all()[i].json);
const lists = [...new Set(rows.map(r => `${r.series_id} ${r.occurrence_id}`))];
return [{ json: { lists, count: lists.length }, pairedItem: { item: 0 } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));
